  function grammarIssues(t) {
    const out = [];
    for (const [rule, re] of GRAMMAR_RULES) { const m = re.exec(t); if (m) out.push({ rule, at: m.index }); }
    return out;
  }
  /* ---------- ซ้ำความชื่อ (label tautology): "การเปลี่ยนผ่าน (XIII) หมายถึงไพ่ใบนี้วางน้ำหนักไว้ที่การเปลี่ยนผ่าน" ---------- */
  const TAUT_RE = new RegExp(REPORT_V + "|คือ|ชวนให้|เป็นสัญญาณให้|วางน้ำหนัก");
  const nameCore = n => String(n || "").replace(/\s*[(（][^)）]*[)）]/g, "").replace(/^(?:ไพ่|ฝันเห็น|ธาตุ|คู่ |ผลรวม )/, "").trim();
  function tautology(t, names) {
    for (const nm of names) {
      let c = nameCore(nm); if (c.length < 4) c = String(nm || "").replace(/\s*[(（][^)）]*[)）]/g, "").trim(); if (c.length < 4) continue;
      const i = t.indexOf(c); if (i < 0) continue;
      const j = t.indexOf(c, i + c.length); if (j < 0) continue;
      const mid = t.slice(i + c.length, j);
      // อนุประโยคเดียวกัน: ระหว่างสองครั้งไม่มีช่องว่าง (ยกเว้นวงเล็บหลักฐานต่อท้ายชื่อ เช่น " (XIII) ")
      const body = mid.replace(/^\s*[(（][^)）]*[)）]\s*/, "");
      if (mid.length <= 80 && TAUT_RE.test(body) && !/\s/.test(body)) return c;
    }
    return null;
  }
  /* ---------- แกนความหมายที่ขัดกันเอง (polarity axes) ----------
     ประโยคบรรยายตัวตนที่อยู่คนละขั้วของแกนเดียวกันต้องไม่อยู่ในคำทำนายเดียว เช่น
     "งานซ้ำเดิมนาน ๆ อาจทำให้คุณเบื่อ" (ชอบสิ่งใหม่) กับ "ยิ่งอยู่ในสายเดิมนาน ผลงานยิ่งลึก" (ยิ่งอยู่ที่เดิมยิ่งดี)
     ใช้กับประโยคบรรยาย ไม่ใช้กับคำแนะนำ (คำแนะนำ "ใจเย็นอีกนิด" ไม่ขัดกับ "คุณใจร้อน") */
  const AXES = [
    ["routine", /ซ้ำ(?:เดิม|ซาก|ไปซ้ำมา).{0,30}เบื่อ|เบื่อ(?:ง่าย|งานซ้ำ|ความจำเจ)|ไม่ชอบความจำเจ|ชอบความแปลกใหม่|ชอบเปลี่ยนแปลงบ่อย|ไม่ชอบอยู่กับที่|อยู่นิ่งไม่ได้/,
      /อยู่ในสายเดิมนาน|ยิ่งอยู่[^\s]{0,12}นาน|ทำสิ่งเดิมได้นาน|ทำงานเดิมได้นาน|ยึดสายงานเดียว|ชอบความเป็นแบบแผน|ชอบกิจวัตรที่คุ้นเคย/],
    ["social", /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:เก็บตัว|รักสันโดษ|ไม่ชอบเข้าสังคม)|ชอบอยู่คนเดียว|ไม่ชอบที่คนเยอะ/, /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:ชอบเข้าสังคม|เข้าสังคมเก่ง|ชอบพบปะผู้คน)|ยิ่งคนเยอะยิ่งสนุก/],
    ["pace", /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:ใจร้อน|ตัดสินใจเร็ว|ตัดสินใจไว)/, /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:ใจเย็น|ตัดสินใจช้า|คิดนานก่อนตัดสินใจ)/],
    ["spend", /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:ใช้เงินเก่ง|มือเติบ|ใช้จ่ายง่าย)/, /เป็นคน(?:ที่)?(?:ค่อนข้าง)?(?:ประหยัด|เก็บเงินเก่ง|มัธยัสถ์)/],
    ["lead", /ชอบเป็นผู้นำ|ชอบนำทีม|ชอบอยู่แถวหน้า/, /ไม่ชอบเป็นผู้นำ|ชอบอยู่เบื้องหลัง|ไม่ชอบเป็นจุดสนใจ/],
    ["express", /แสดงความรู้สึกตรง ๆ|เปิดเผยความรู้สึกง่าย|รักแบบเปิดเผย/, /เก็บความรู้สึก(?:เก่ง|ไว้ในใจ)|ไม่ค่อยแสดงความรู้สึก|รักแบบเงียบ ๆ/],
  ];
  // ขั้วของประโยคบนแต่ละแกน: [["routine", 0], …]
  function polesOf(t) { if (isImperative(t)) return []; const out = []; for (const [id, a, b] of AXES) { if (a.test(t)) out.push([id, 0]); if (b.test(t)) out.push([id, 1]); } return out; }
  // หัวข้อที่ไม่ควรมีเนื้อหาเรื่องรักล้วน ๆ (เงิน งาน มิตรภาพ)
  const LOVE_STRICT = /ความรัก|คนรัก|คู่รัก|แฟน|คนโสด|คนมีคู่|คู่ครอง|เนื้อคู่|คู่ชีวิต|ออกเดท/;
  const OWN_LEX = { money: /เงิน|ทรัพย์|ออม|รายได้|รายรับ|รายจ่าย|ใช้จ่าย|ลาภ|บัญชี|งบ|ลงทุน|หนี้|ซื้อ|ขาย|ค้า/, work: /งาน|อาชีพ|ทีม|หัวหน้า|ลูกค้า|เรียน|โปรเจกต์|ผลงาน|ธุรกิจ|ตำแหน่ง/, social: /เพื่อน|ผู้คน|คนรอบ|สังคม|ทีม|ผู้ใหญ่|เครือข่าย|คนรู้จัก|ส่วนรวม|ญาติ|พี่น้อง/ };
  // ตรวจทีละช่วง (ภาษาไทยคั่นอนุประโยคด้วยช่องว่าง) — ช่วงที่พูดเรื่องรักล้วน ๆ ในหัวข้อเงิน/งาน/มิตรภาพ ถือว่าผิดหัวข้อ
  const loveOnlyIn = (t, sec) => !!OWN_LEX[sec] && String(t).split(/\s+/).some(c => c.length >= 12 && LOVE_STRICT.test(c) && !OWN_LEX[sec].test(c));
  // ป้ายชื่อสำหรับประโยค: ตัดสัญลักษณ์ดิบ ("เส้นที่ 1 · จุดเริ่มต้น (หยางเก่า → หยิน)" → "เส้นที่ 1 (จุดเริ่มต้น)")
  function proseLabel(l) {
    let t = String(l || "").trim();
    if (/·/.test(t)) {
      const parts = t.split(/\s*·\s*/), head = parts[0], rest = parts.slice(1).join(" ").replace(/\s*[(（][^)）]*[)）]\s*$/, "").trim();
      t = rest && !/[()（）]/.test(head) ? head + " (" + rest + ")" : head;
    }
    return t.replace(/\s*[(（][^)）]*(?:→|←)[^)）]*[)）]/g, "").replace(/\s*(?:→|←)\s*/g, " ").replace(/[•|]/g, " ").replace(/\s{2,}/g, " ").trim();
  }

  /* ======================= โทนของสิ่งที่พบ (favourable / neutral / caution) และคำเตือนอย่างนุ่มนวล =======================
     facts.items[].tone = "favourable" | "neutral" | "caution" (ไม่ระบุ: polarity "challenge" → caution, strength ≥ 0.5 → favourable, อื่น ๆ → neutral)
     คำทำนายไม่ใช่บวกล้วน: เมื่อตำราชี้ว่าเรื่องใดตึง จะบอกตรง ๆ แต่ใช้ถ้อยคำอ้อม ("ช่วงนี้ตำราชี้ว่า…อาจตึงมือ") และต้องมีสิ่งที่ทำได้ตามมาเสมอ
     ยังห้ามทำนายความตาย ความเจ็บป่วย อุบัติเหตุ การนอกใจ การหย่าร้าง ภัยพิบัติ เลขเสี่ยงโชค และการเสียเงินแก้ดวง (ตัวกรอง isSafe เดิม) */
  const TONES = ["favourable", "neutral", "caution"];
  const toneOf = it => (it && TONES.indexOf(it.tone) >= 0 ? it.tone : it && it.polarity === "challenge" ? "caution" : it && (it.strength || 0) >= 0.5 ? "favourable" : "neutral");
  // ประโยคนำของจุดที่ควรระวัง (หัวข้อ → ถ้อยคำ) — อ้อม ไม่ฟันธง
  const CAUTION_LEAD_TH = {
    money: ["ช่วงนี้ตำราชี้ว่าเรื่องเงินอาจตึงมืออยู่บ้าง", "ด้านการเงิน ตำรามองว่าเป็นช่วงที่ควรระวังการใช้จ่าย"],
    work: ["ช่วงนี้ตำราชี้ว่างานอาจต้องใช้แรงมากกว่าปกติ", "ด้านการงาน ตำรามองว่าเป็นช่วงที่ควรค่อย ๆ เดิน ไม่เร่งเกินไป"],
    love: ["ช่วงนี้ตำราชี้ว่าความสัมพันธ์อาจต้องการความเข้าใจมากขึ้น", "เรื่องหัวใจ ตำรามองว่าเป็นช่วงที่ควรใจเย็นกับกันและกัน"],
    overview: ["ตำราชี้ว่ามีบางเรื่องที่ควรระมัดระวังในช่วงนี้", "ช่วงนี้ตำรามองว่าเป็นจังหวะที่ควรเดินอย่างรอบคอบ"],
  };
  const CAUTION_ACTION_TH = {
    money: ["ควรวางแผนใช้จ่ายให้รัดกุม และกันเงินสำรองไว้สักก้อน", "ลองจดรายจ่ายสักสองสัปดาห์ แล้วตัดรายการที่ไม่จำเป็นออก"],
    work: ["ลองแบ่งงานเป็นขั้นเล็ก ๆ และเผื่อเวลาไว้ให้ตัวเอง", "ควรตรวจรายละเอียดให้รอบคอบก่อนส่งงาน และขอความช่วยเหลือเมื่อจำเป็น"],
    love: ["ลองคุยกันด้วยน้ำเสียงนุ่มนวล ฟังให้มากกว่าพูด", "ควรให้เวลากันมากขึ้น และบอกความรู้สึกอย่างตรงไปตรงมาแต่อ่อนโยน"],
    overview: ["ควรตัดสินใจเรื่องสำคัญอย่างใจเย็น และวางแผนสำรองไว้", "ลองทำทีละเรื่อง พักให้พอ และทบทวนแผนเป็นระยะ"],
  };
  const CAUTION_LEAD_ZH = {
    money: ["这段时间财务上可能会紧一些", "财务方面，这段时间要多留意开支"],
    work: ["这段时间工作上可能要多花些力气", "工作方面，这段时间宜稳步推进，不要太赶"],
    love: ["这段时间感情上可能需要多一些体谅", "感情方面，这段时间彼此都要多一点耐心"],
    overview: ["这段时间有些事情需要多留心", "这段时间宜稳一点，凡事多想一步"],
  };
  const CAUTION_ACTION_ZH = {
    money: ["建议把开支计划做细一些，留一笔备用金", "不妨记两周账，把不必要的支出先停下来"],
    work: ["不妨把工作拆成小步骤，给自己留一点余地", "建议交付前多核对细节，需要时就请人帮忙"],
    love: ["不妨用温和的语气多沟通，多听少说", "建议多留一些相处的时间，真诚又温柔地表达感受"],
    overview: ["建议重要的决定放慢一点，并准备好备用方案", "不妨一次只做一件事，休息充足，定期回顾计划"],
  };
  const CAUTION_LEAD_EN = {
    money: ["The traditional reading suggests money may feel a little tight for a while", "Where money is concerned, tradition sees this as a time to keep a closer eye on spending"],
    work: ["The traditional reading suggests work may take a bit more effort than usual for now", "At work, tradition sees this as a time to move steadily rather than rush"],
    love: ["The traditional reading suggests your relationship may need a little extra understanding for now", "In matters of the heart, tradition sees this as a time for patience with each other"],
    overview: ["The traditional reading points to a few things that call for a little extra care at the moment", "Tradition sees this as a time to move thoughtfully and think one step ahead"],
  };
  const CAUTION_ACTION_EN = {
    money: ["A good way to handle this is to plan your spending a little more closely and set aside a small reserve", "Try noting down your spending for two weeks and pausing anything that isn't needed"],
    work: ["Try breaking the work into small steps and leaving yourself some breathing room", "A good way to handle this is to check the details before you hand work in, and to ask for help when you need it"],
    love: ["Try talking things through in a gentle tone, and listen more than you speak", "A good way to handle this is to make more time for each other and to say how you feel honestly but kindly"],
    overview: ["A good way to handle this is to make important decisions calmly and keep a backup plan", "Try taking one thing at a time, resting enough, and reviewing your plans now and then"],
  };
  const cautionArea = (it, sec) => (CAUTION_LEAD_TH[sec] ? sec : (it.tags || []).find(t => CAUTION_LEAD_TH[t]) || "overview");
  /* lint "caution-gentle": ประโยคที่บอกจุดควรระวังต้องนุ่มนวล (ไม่มีถ้อยคำรุนแรง/ฟันธง) และต้องมีสิ่งที่ทำได้ในประโยคเดียวกันหรือประโยคถัดไป */
  const CAUTION_MARK_TH = /ควรระวัง|ตึงมือ|ระมัดระวัง|ต้องใช้แรงมากกว่าปกติ|ต้องการความเข้าใจมากขึ้น|ควรใจเย็นกับกันและกัน|เดินอย่างรอบคอบ|จุดที่ควรใส่ใจ/;
  const CAUTION_MARK_ZH = /紧一些|多留意|多留心|多花些力气|多一些体谅|多一点耐心|宜稳/;
  const CAUTION_MARK_EN = /a little tight|keep a closer eye|a bit more effort|move steadily rather than rush|a little extra understanding|patience with each other|a little extra care|move thoughtfully/i;
  const HARSH_EN = /\b(?:terrible|awful|dreadful|disastrous|doomed|hopeless|ruin(?:ed|ous)?|catastroph\w*|bad luck|misfortune|unlucky|cursed|crisis|failure|fail(?:s|ed)?|bleak|grim)\b/i;
  const ACTION_EN = /\b(?:a good way to handle this|a simple adjustment|a good next step|this is a good time to|try|it would help|consider|plan|set aside|note|take|make time|talk|listen|check|ask|keep|choose|write|rest|review|put|pause|start|set|spend|give|use|tell|share|leave|wear|open|clear|tidy|turn|practice|break)\b/i;
  const HARSH_TH = /แย่มาก|ย่ำแย่|เลวร้าย|ร้ายแรง|หายนะ|พังทลาย|ล้มเหลวแน่|ไม่มีทาง|ดวงตก|ดวงซวย|อับโชค|วิกฤต/;
  const HARSH_ZH = /很糟|糟糕|非常差|灾|厄运|倒霉|失败|完蛋|没有希望/;
  const ACTION_TH = /วิธีปรับ|เคล็ดเสริมดวง|สิ่งที่ทำได้|วิธีเสริม|เลือก|ตั้ง|ระมัดระวัง|ควร|ลอง|ค่อย ๆ|วางแผน|แบ่ง|จด|เผื่อ|ตรวจ|ทบทวน|พัก|คุย|ฟัง|ให้เวลา|กันเงิน|ตัดสินใจ/;
  const ACTION_ZH = /调整的方法|宜|建议|不妨|可以|记得|试着|先|把|多/;
  function cautionIssues(result) {
    const out = [], zh = result && result.lang === "zh", en = result && result.lang === "en";
    for (const s of (result && result.sections) || []) {
      const units = (s.paragraphs || []).flatMap(p => (zh ? p.split(/(?<=[。！？])/).map(x => x.trim()).filter(Boolean) : en ? enSentences(p) : sentences(p)));
      units.forEach((u, i) => {
        if (!(zh ? CAUTION_MARK_ZH : en ? CAUTION_MARK_EN : CAUTION_MARK_TH).test(u)) return;
        if ((zh ? HARSH_ZH : en ? HARSH_EN : HARSH_TH).test(u)) out.push({ rule: "caution-gentle", section: s.id, excerpt: "harsh: " + u.slice(0, 90) });
        const win = units.slice(i, i + (en ? 5 : 10)).join(" ").slice(0, en ? 900 : 420);
        if (!(zh ? ACTION_ZH : en ? ACTION_EN : ACTION_TH).test(win)) out.push({ rule: "caution-gentle", section: s.id, excerpt: "no action: " + u.slice(0, 90) });
      });
    }
    return out;
  }

