      if ((m = /^cn\.year\.(\d+)\.(\w+)$/.exec(id))) return ["cn.animal." + m[1], "cn.el." + m[2]];
      if ((m = /^today\.bhumi\.(\w+)$/.exec(id))) return ["bhumi." + m[1]];
