  // 数字与汉字之间留空格（"生命灵数 7 这一点"），中文标点前不留空格
  const zhTidy = t => String(t).replace(/(\s\d+)(?=[\u4e00-\u9fff])/g, "$1 ").replace(/\s+(?=[，。、：；！？）])/g, "");
  const zhEnd = s => { const t = zhTidy(s); return /[。！？]$/.test(t) ? t : t + "。"; };
