        if (/นิยม|ยอดนิยม|มั่นคง/.test(cl) && !/เลี่ยง|ระวัง|ใส่ใจ/.test(cl)) for (const x of prs) if (care.has(x)) push("numbers-polarity", s.id, "praise " + x + " (care pair): " + cl.slice(0, 90));
